// --- Progress Tracker ---
class ProgressTracker {
    int total, current;
    std::mutex mtx;
public:
    ProgressTracker(int t) : total(t), current(0) {}

    void update(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx);
        current++;
        double pct = (double)current / total * 100;
        Logger::info(std::string("Processing: ") + name + " - " + std::to_string(current) + "/" + std::to_string(total) + " (" + std::to_string((int)pct) + "%)");
    }
    void finish() {
        std::lock_guard<std::mutex> lock(mtx);
        Logger::info("Processing complete.");
    }
};

