    int pos_count = 0, neg_count = 0;
    for (const auto& r : results) {
        out << r.file << "," << r.sentiment << ",";
        for(const auto& k : r.keywords) out << k << ",";
        out << std::fixed << std::setprecision(4) << r.avg_time << "," << sales.revenue << "\n";

        if (r.sentiment == "positive") pos_count++;
