/**
 * Simple Logger Class
 * Replaces external logging frameworks (like Poco or Log4cpp) to keep the code dependency-light.
 * Outputs timestamped messages to console (stdout/stderr).
 */
class Logger {
public:
    // Logs an informational message with a timestamp (milliseconds since epoch).
    static void info(const std::string& msg) {
        auto now = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()).count();
        std::cout << "[" << duration << "] [INFO] " << msg << "\n";
    }

    // Logs a warning message. Used for non-critical errors (e.g., skipped files).
    static void warn(const std::string& msg) {
        auto now = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()).count();
        std::cout << "[" << duration << "] [WARN] " << msg << "\n";
    }

    // Logs an error message to stderr (red output simulation). Used for critical failures.
    static void error(const std::string& msg) {
        std::cerr << "[" << std::chrono::system_clock::now().time_since_epoch().count() << "] [ERR] " << msg << "\n";
    }
};

// -----------------------------------------------------------------------------
