/**
 * NlpResult: Stores the output of the text analysis engine.
 * Represents a single record after it has been processed and analyzed.
 */
struct NlpResult {
    std::string file;       // Identifier (filename or line index)
    std::string sentiment;  // "positive", "negative", or "neutral"
    std::vector<std::string> keywords; // Extracted relevant terms
    double avg_time;        // Simulated processing time (seconds)
};

/**
 * SalesResult: Stores aggregated sales metrics derived from the analysis.
 * Used in the final reporting phase.
 */
struct SalesResult {
    double revenue; // Total simulated revenue
    int count;      // Total number of records processed
    std::vector<std::string> top_products; // Most frequent positive product mentions
};

// -----------------------------------------------------------------------------
// 3. PREPROCESSING LOGIC
// -----------------------------------------------------------------------------

/**
 * clean_text
 * Description: Normalizes raw text data.
 * 1. Removes non-alphanumeric characters (keeping spaces).
 * 2. Converts all characters to lowercase.
 * 3. Tokenizes by whitespace.
 * 4. Filters out very short words (length <= 2) as they are often noise (e.g., "a", "is").
 * 5. Re-joins tokens with spaces to form the cleaned string.
 * 
 * @param text The original raw string.
 * @return The cleaned, normalized string.
 */
std::string clean_text(const std::string& text) {
    // Safety check for empty input
    if (text.empty()) return "";

    // Regex pattern [^a-zA-Z0-9\s] matches anything that is NOT a letter, digit, or space.
    // We replace these with a single space.
    std::regex re("[^a-zA-Z0-9\s]");
    std::string cleaned = std::regex_replace(text, re, " ");

    // Convert the entire string to lowercase
    std::transform(cleaned.begin(), cleaned.end(), cleaned.begin(), ::tolower);

    // Tokenize: Create a stringstream to split the string by spaces one by one.
    std::stringstream ss(cleaned);
    std::string word;
    std::vector<std::string> tokens;

    // Loop until no more words are found
    while (ss >> word) {
        // Keep only words longer than 2 characters
        if (word.length() > 2) {
            tokens.push_back(word);
        }
    }

    // Reconstruct the string by concatenating all valid tokens with spaces
    return std::accumulate(tokens.begin(), tokens.end(), std::string(" "), 
                          [](const std::string& a, const std::string& b) {
                              return a + " " + b;
                          });
}

/**
 * standardize_timestamps
 * Description: Placeholder for timestamp handling.
 * In a full implementation, this would parse various date formats (YYYY-MM-DD, etc.).
 * Here, it simply maps invalid/empty strings to "MISSING" and keeps valid ones.
 * 
 * @param times Vector of raw timestamp strings.
 * @return Vector of standardized strings.
 */
std::vector<std::string> standardize_timestamps(const std::vector<std::string>& times) {
    std::vector<std::string> results;
    for (const auto& t : times) {
        if (t.empty() || t == "NULL") {
            results.push_back("MISSING"); // Mark invalid as "MISSING"
        } else {
            results.push_back(t); // Assume valid if not empty/null
        }
    }
    return results;
}

/**
 * handle_missing_value
 * Description: A generic utility to standardize null values in columns.
 * Converts empty strings or "NULL" strings into a uniform marker: "MISSING".
 * 
 * @param val The value to check.
 * @return The standardized value.
 */
std::string handle_missing_value(const std::string& val) {
    if (val.empty() || val == "NULL" || val == "null") {
        return "MISSING";
    }
    return val;
}

