 * Description: Simulates a Natural Language Processing pipeline.
 * Performs sentiment analysis and keyword extraction on the input text.
 * Note: This is a mock function. In production, integrate with a real ML library (e.g., TensorFlow/PyTorch wrapped in C++).
 * 
 * @param text The input text to analyze.
 * @return NlpResult containing sentiment score, keywords, and estimated time.
 */
NlpResult mock_nlp_analyze(const std::string& text) {
    if (text.empty()) return {"", "neutral", {}, 0.0}; // Fail-safe for empty input

    // 1. Basic Prep: Create a copy for analysis
    std::string lower = text;
    std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);

    // 2. Sentiment Analysis: Simple rule-based heuristic
    std::string sentiment = "neutral";
    if (lower.find("angry") != std::string::npos || lower.find("complain") != std::string::npos) {
        sentiment = "negative";
    } else if (lower.find("happy") != std::string::npos || lower.find("great") != std::string::npos) {
        sentiment = "positive";
    }

    // 3. Keyword Extraction: Scan for pre-defined business terms
    std::vector<std::string> keywords;
    std::set<std::string> dict = {"service", "product", "price", "refund", "error"};
    std::stringstream ss(text);
    std::string word;

    while (ss >> word) {
        // Check if word is in our dictionary AND is long enough to be meaningful
        if (dict.count(word) && word.length() > 3) {
            keywords.push_back(word);
        }
    }

    // 4. Cost Estimation: Simulated CPU time proportional to text length
    double time_cost = static_cast<double>(text.length()) * 0.001;

    return {text, sentiment, keywords, time_cost};
}

/**
 * mock_agg_sales
 * Description: Simulates the aggregation phase for financial reporting.
 * Calculates total revenue and identifies top products based on a mock logic.
 * 
 * @param data Vector of NlpResult objects.
 * @return SalesResult containing total revenue, record count, and top products.
 */
SalesResult mock_agg_sales(const std::vector<NlpResult>& data) {
    double total_rev = 0.0;
    int count = 0;
    std::vector<std::string> products; // Using vector instead of map for brevity in this mock

    for (const auto& r : data) {
        // Logic: Dummy revenue calculation based on string length for demo purposes
        // In reality, this would join with a DB sales table.
        total_rev += r.file.length() * 10.0; 
        count++;

        // If sentiment is positive, track "Premium" as a top product
        if (r.sentiment == "positive") {
            // Only add if not already present (simple dedup)
            bool exists = false;
            for (const auto& p : products) {
                if (p == "Premium") exists = true;
            }
            if (!exists) {
                products.push_back("Premium");
            }
        }
    }

    return {total_rev, count, products};
}

