        history.push_back(data); // Append data to internal vector
    }
    void clear() { history.clear(); }
};

/**
 * ProgressTracker
 * Description: A thread-safe utility class to report progress in a multi-threaded or long-running process.
 * Ensures output isn't interleaved or lost using mutex locks.
 */
class ProgressTracker {
    int total_tasks, current_task;
    std::mutex mtx; // Mutex to ensure thread safety of the counter

public:
    ProgressTracker(int t) : total_tasks(t), current_task(0) {}

    void update(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx); // Lock the mutex for thread safety
        current_task++;
        double pct = (double)current_task / total_tasks * 100;

        // Format: "Processing: Name - 42/100 (42%)"
        Logger::info(std::string("Processing: ") + name + " - " + std::to_string(current_task) + "/" + std::to_string(total_tasks) + " (" + std::to_string((int)pct) + "%)");
    }

    void finish() {
        std::lock_guard<std::mutex> lock(mtx);
        Logger::info("Processing complete.");
    }
};

/**
 * read_all_files
 * Description: Iterates through the input directory and reads content of supported file types.
 * Filters out directories and only processes .csv, .json, and .txt files.
 * 
 * @param dir Path to the root directory containing files.
 * @return Vector containing the raw text content of all files.
 */
std::vector<std::string> read_all_files(const fs::path& dir) {
    std::vector<std::string> data;
    try {
        // Directory Iterator scans files recursively (or top-level depending on impl)
        for (const auto& entry : fs::directory_iterator(dir)) {
            // Only process regular files
            if (entry.is_regular_file()) {
                Logger::info("Reading: " + entry.path().string());

                // Check extension strictly
                if (entry.path().extension() == ".json" || 
                    entry.path().extension() == ".csv" || 
                    entry.path().extension() == ".txt") {

                    // Read file content into a string
                    data.push_back(fs::read_file(entry.path().string()).string());
                }
            }
        }
    } catch (const std::exception& e) {
        // Handle errors gracefully (e.g., permission denied, file read error)
        Logger::warn("Failed to read directory or file access error: " + e.what());
    }
    return data;
}

// -----------------------------------------------------------------------------
// 6. MAIN ENTRY POINT
// -----------------------------------------------------------------------------

/**
 * main
 * Description: The orchestration engine for the entire data pipeline.
 * Coordinates reading, cleaning, analysis, aggregation, and reporting.
 * 
 * @return Exit code (0 for success, non-zero for failure).
 */
int main() {
    // 1. Initialization
    Config cfg; // In a full app, parse command line args here
    fs::path input_dir(cfg.input_dir);
    fs::path output_dir(cfg.output_dir);

    // Ensure output directory exists
    if (!fs::exists(output_dir)) {
        fs::create_directories(output_dir);
    }

    Logger::info("Starting Enterprise Data Pipeline...");

    // 2. Phase 1: Data Ingestion
    // Read all raw data from the input directory
    std::vector<std::string> raw_data = read_all_files(input_dir);

    // Initialize the progress tracker for the pipeline
    ProgressTracker tracker(raw_data.size());

    // 3. Phase 2: Preprocessing & Analysis
    std::vector<NlpResult> results;

    for (size_t i = 0; i < raw_data.size(); ++i) {
        // Skip empty files/lines to avoid errors later
        if (raw_data[i].empty()) {
            Logger::warn("Skipping empty file line " + std::to_string(i));
            tracker.update("EmptyLine"); // Report progress
            continue;
        }

        // Clean the text
        std::string text = clean_text(raw_data[i]);

        if (!text.empty()) {
            // Run NLP Analysis
            auto r = mock_nlp_analyze(text);

            // Assign a unique identifier (filename or index) if not already set
            if (r.file.empty()) r.file = std::to_string(i);

            results.push_back(r);
        }

        tracker.update("Line_" + std::to_string(i));
    }

    // 4. Phase 3: Edge Case Handling (Empty Data)
    if (results.empty()) {
        Logger::warn("No valid data processed. Generating empty report.");

        // Generate empty CSV report to ensure pipeline exit code is success
        fs::path report = output_dir / "preprocessed_daily_" + std::to_string(std::time(0)) + ".csv";
        std::ofstream out(report);
        out << "file,sentiment,keywords,avg_time,revenue\n"; // Write header only
        out.close();

        return 0; // Exit successfully
    }

    // 5. Phase 4: Aggregation
    // Calculate business metrics (Revenue, counts)
    SalesResult sales = mock_agg_sales(results);

    // 6. Phase 5: Reporting
    // Write the final processed report to disk
    fs::path report = output_dir / "preprocessed_daily_" + std::to_string(std::time(0)) + ".csv";
    std::ofstream out(report);

    if (!out.is_open()) {
        Logger::error("Failed to open output file: " + report.string());
        return 1;
    }

    out << "file,sentiment,keywords,avg_time,revenue\n"; // Write header

    int pos_count = 0;
    int neg_count = 0;

    // Iterate through results and format CSV output
    for (const auto& r : results) {
        out << r.file << ",";                          // File ID
        out << r.sentiment << ",";                     // Sentiment

        // Join keywords with commas
        out << "(";
        for (size_t k = 0; k < r.keywords.size(); ++k) {
            out << r.keywords[k];
            if (k < r.keywords.size() - 1) out << ", ";
        }
        out << ")"; // Close keywords
        out << ",";

        out << std::fixed << std::setprecision(4) << r.avg_time << ","; // Time
        out << sales.revenue << "\n"; // Revenue

        // Aggregate sentiment counts for summary
        if (r.sentiment == "positive") pos_count++;
        else neg_count++;
    }

    out.close(); // Close stream to flush buffers
    Logger::info("Report generated successfully: " + report.string());

    // Final Summary
    Logger::info("Sentiment Distribution: Positive=" + std::to_string(pos_count) + 
                 ", Negative=" + std::to_string(neg_count) + 
                 ", Total=" + std::to_string(results.size()));

    return 0;
}
